function emptyState() {
  return { byId: Object.create(null), order: [] };
}

function partReducer(state, action) {
  const current = state === undefined ? emptyState() : state;
  if (action === null || typeof action !== 'object') return current;

  if (action.type === 'REPLACE_PARTS') {
    if (!Array.isArray(action.parts)) throw new TypeError('parts must be an array');

    const byId = Object.create(null);
    const order = [];
    const seen = new Set();
    for (const part of action.parts) {
      if (part === null || typeof part !== 'object' ||
          typeof part.id !== 'string' || part.id.length === 0 || seen.has(part.id) ||
          typeof part.label !== 'string' || typeof part.hours !== 'number' ||
          !Number.isFinite(part.hours) || part.hours < 0) {
        throw new TypeError('Invalid or duplicate part');
      }
      seen.add(part.id);
      order.push(part.id);
      byId[part.id] = { id: part.id, label: part.label, hours: part.hours, pinned: false };
    }
    return { byId, order };
  }

  if (action.type === 'PIN_PART' || action.type === 'UNPIN_PART') {
    if (typeof action.id !== 'string' || action.id.length === 0) {
      throw new TypeError('Invalid part id');
    }
    if (!Object.prototype.hasOwnProperty.call(current.byId, action.id)) return current;

    const byId = Object.create(null);
    for (const key of Reflect.ownKeys(current.byId)) {
      byId[key] = current.byId[key];
    }

    const part = current.byId[action.id];
    byId[action.id] = {
      ...part,
      id: part.id,
      label: part.label,
      hours: part.hours,
      pinned: action.type === 'PIN_PART'
    };
    return { byId, order: current.order };
  }

  return current;
}

module.exports = partReducer;
